// JesutofunmiOS — single-file Worker build (generated by build-worker.mjs; do not edit by hand).
// Contains: shared helpers + API handlers (from functions/api) + the app HTML with CSS/JS inlined.

// JesutofunmiOS — shared helpers for Pages Functions.
// Files beginning with "_" are not routes; they are importable modules.

const OWNERS = ['Jesutofunmi', 'Nayden', 'Claude', 'ChatGPT', 'Instinct', 'Unassigned'];
const ACTORS = ['Jesutofunmi', 'Nayden', 'Claude', 'ChatGPT', 'Instinct'];
const STATUSES = ['todo', 'doing', 'waiting', 'done'];
const SESSION_COOKIE = 'lhq_session';

function json(data, status = 200, extraHeaders = {}) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { 'Content-Type': 'application/json', ...extraHeaders },
  });
}

function err(message, status = 400) {
  return json({ error: message }, status);
}

function nowISO() {
  return new Date().toISOString();
}

function todayISO() {
  return new Date().toISOString().slice(0, 10);
}

// The session token is derived from the passcode, never the passcode itself.
// Anything that knows TEAM_PASSCODE can recompute it; the cookie only ever
// carries this digest.
async function sessionToken(passcode) {
  const data = new TextEncoder().encode(`${passcode}::jesutofunmios::session-v1`);
  const digest = await crypto.subtle.digest('SHA-256', data);
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

function readSessionCookie(request) {
  const cookie = request.headers.get('Cookie') || '';
  const match = cookie.match(new RegExp(`(?:^|;\\s*)${SESSION_COOKIE}=([^;]+)`));
  return match ? match[1] : null;
}

// Actor attribution: the client sends "Acting as" on every write, either as
// the X-Actor header or an `actor` field in the JSON body.
function getActor(request, body) {
  const raw = request.headers.get('X-Actor') || (body && body.actor) || '';
  const actor = String(raw).trim().slice(0, 40);
  return ACTORS.includes(actor) ? actor : 'Jesutofunmi';
}

async function parseBody(request) {
  try {
    const body = await request.json();
    return body && typeof body === 'object' ? body : null;
  } catch {
    return null;
  }
}

function cleanStr(value, max = 5000) {
  if (value === undefined || value === null) return '';
  return String(value).slice(0, max);
}

function validDate(value) {
  if (value === null || value === undefined || value === '') return null;
  const s = String(value);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return undefined; // undefined = invalid
  const d = new Date(`${s}T00:00:00Z`);
  if (Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== s) return undefined;
  return s;
}

function validOwner(value, fallback = 'Unassigned') {
  if (value === undefined || value === null || value === '') return fallback;
  return OWNERS.includes(value) ? value : undefined; // undefined = invalid
}

function validStatus(value, fallback = 'todo') {
  if (value === undefined || value === null || value === '') return fallback;
  return STATUSES.includes(value) ? value : undefined; // undefined = invalid
}

// Every mutation writes an activity row. task_id is null for digest/deadline events.
async function writeActivity(env, { taskId = null, actor, action, note = '' }) {
  await env.DB.prepare(
    'INSERT INTO activity (task_id, actor, action, note, created_at) VALUES (?, ?, ?, ?, ?)'
  )
    .bind(taskId, actor, action, cleanStr(note, 1000), nowISO())
    .run();
}

// Daily reports: one report per (date, author). The author is whose report it
// is; created_by is who posted it — Jesutofunmi's report is posted by Instinct,
// so the two routinely differ.
function validAuthor(value) {
  if (value === undefined || value === null || value === '') return undefined;
  return ACTORS.includes(value) ? value : undefined; // undefined = invalid
}

const REPORTS_TABLE_SQL = `CREATE TABLE IF NOT EXISTS reports (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  date       TEXT NOT NULL,
  author     TEXT NOT NULL,
  body       TEXT NOT NULL DEFAULT '',
  created_by TEXT DEFAULT '',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
)`;

// Self-migration: creates the reports table (and its indexes) when missing.
// Idempotent and cheap, so it runs on the API request path — existing
// databases gain the table with no manual console step.
async function ensureReportsTable(env) {
  if (!env || !env.DB) return;
  await env.DB.batch([
    env.DB.prepare(REPORTS_TABLE_SQL),
    env.DB.prepare('CREATE UNIQUE INDEX IF NOT EXISTS idx_reports_date_author ON reports(date, author)'),
    env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_reports_date ON reports(date)'),
  ]);
}

// ---- ./functions/api/auth.js ----
// POST /api/auth — body { passcode, actor }
// On a passcode match, sets an HttpOnly session cookie whose value is a
// SHA-256 token derived from the passcode. The passcode itself is never
// stored client-side and never echoed back.

async function hAuthPost({ request, env }) {
  if (!env.TEAM_PASSCODE) {
    return err('TEAM_PASSCODE is not configured on the server.', 500);
  }
  const body = await parseBody(request);
  if (!body || typeof body.passcode !== 'string') {
    return err('Body must be JSON with a passcode.', 400);
  }

  // Compare digests rather than the raw strings.
  const given = await sessionToken(body.passcode);
  const expected = await sessionToken(env.TEAM_PASSCODE);
  if (given !== expected) {
    return err('Incorrect passcode.', 401);
  }

  const token = expected;
  const maxAge = 60 * 60 * 24 * 30; // 30 days
  return json(
    { ok: true, actor: getActor(request, body) },
    200,
    {
      'Set-Cookie': `${SESSION_COOKIE}=${token}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${maxAge}`,
    }
  );
}

// ---- ./functions/api/logout.js ----
// POST /api/logout — clears the session cookie.

async function hLogoutPost() {
  return json(
    { ok: true },
    200,
    {
      'Set-Cookie': `${SESSION_COOKIE}=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0`,
    }
  );
}

// ---- ./functions/api/state.js ----
// GET /api/state — everything the SPA needs in one call:
// open tasks + latest 50 done, latest digest in full, digest index,
// deadlines sorted by date, latest 30 activity rows, and every daily
// report from the last 7 days.

async function hStateGet({ env }) {
  await ensureReportsTable(env);

  const open = await env.DB.prepare(
    `SELECT * FROM tasks WHERE status != 'done'
     ORDER BY CASE WHEN due IS NULL THEN 1 ELSE 0 END, due ASC, id ASC`
  ).all();

  const done = await env.DB.prepare(
    `SELECT * FROM tasks WHERE status = 'done'
     ORDER BY updated_at DESC, id DESC LIMIT 50`
  ).all();

  const latestDigest = await env.DB.prepare(
    'SELECT * FROM digests ORDER BY date DESC, id DESC LIMIT 1'
  ).first();

  const digests = await env.DB.prepare(
    'SELECT id, date, title, created_by, created_at FROM digests ORDER BY date DESC, id DESC'
  ).all();

  const deadlines = await env.DB.prepare(
    'SELECT * FROM deadlines ORDER BY date ASC, id ASC'
  ).all();

  const activity = await env.DB.prepare(
    'SELECT * FROM activity ORDER BY id DESC LIMIT 30'
  ).all();

  // Last 7 days of daily reports (today plus the six days before), newest
  // date first. Full rows — the Reports view renders them without extra calls.
  const weekStart = new Date(Date.now() - 6 * 86400000).toISOString().slice(0, 10);
  const reports = await env.DB.prepare(
    'SELECT * FROM reports WHERE date >= ? ORDER BY date DESC, author ASC'
  )
    .bind(weekStart)
    .all();

  return json({
    tasks: [...(open.results || []), ...(done.results || [])],
    latestDigest: latestDigest || null,
    digests: digests.results || [],
    deadlines: deadlines.results || [],
    activity: activity.results || [],
    reports: reports.results || [],
  });
}

// ---- ./functions/api/tasks.js ----
// POST /api/tasks — create a task.
// Body: { title (required), details, owner, status, due, evidence, actor }

async function hTasksPost({ request, env }) {
  const body = await parseBody(request);
  if (!body) return err('Body must be valid JSON.', 400);

  const title = cleanStr(body.title, 300).trim();
  if (!title) return err('title is required.', 400);

  const owner = validOwner(body.owner);
  if (owner === undefined) return err('owner is not a recognised name.', 400);

  const status = validStatus(body.status);
  if (status === undefined) return err('status must be one of: todo, doing, waiting, done.', 400);

  const due = validDate(body.due);
  if (due === undefined) return err('due must be an ISO date (YYYY-MM-DD) or null.', 400);

  const actor = getActor(request, body);
  const ts = nowISO();

  const result = await env.DB.prepare(
    `INSERT INTO tasks (title, details, owner, status, due, created_by, updated_by, evidence, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  )
    .bind(
      title,
      cleanStr(body.details),
      owner,
      status,
      due,
      actor,
      actor,
      cleanStr(body.evidence, 2000),
      ts,
      ts
    )
    .run();

  const id = result.meta.last_row_id;
  await writeActivity(env, { taskId: id, actor, action: 'created', note: title });

  const task = await env.DB.prepare('SELECT * FROM tasks WHERE id = ?').bind(id).first();
  return json({ task }, 201);
}

// ---- ./functions/api/tasks/[id].js ----
// PATCH /api/tasks/:id — partial update.
// Body may include any of: title, details, owner, status, due, evidence, actor.
// Writes an activity row: 'status_changed' when the status moved, else 'updated'.

async function hTaskPatch({ request, env, params }) {
  const id = Number(params.id);
  if (!Number.isInteger(id) || id <= 0) return err('Invalid task id.', 400);

  const existing = await env.DB.prepare('SELECT * FROM tasks WHERE id = ?').bind(id).first();
  if (!existing) return err('Task not found.', 404);

  const body = await parseBody(request);
  if (!body) return err('Body must be valid JSON.', 400);

  const next = { ...existing };
  const changed = [];

  if ('title' in body) {
    const title = cleanStr(body.title, 300).trim();
    if (!title) return err('title cannot be empty.', 400);
    if (title !== next.title) { next.title = title; changed.push('title'); }
  }
  if ('details' in body) {
    const details = cleanStr(body.details);
    if (details !== next.details) { next.details = details; changed.push('details'); }
  }
  if ('owner' in body) {
    const owner = validOwner(body.owner);
    if (owner === undefined) return err('owner is not a recognised name.', 400);
    if (owner !== next.owner) { next.owner = owner; changed.push(`owner → ${owner}`); }
  }
  if ('status' in body) {
    const status = validStatus(body.status);
    if (status === undefined) return err('status must be one of: todo, doing, waiting, done.', 400);
    if (status !== next.status) { next.status = status; changed.push(`status ${existing.status} → ${status}`); }
  }
  if ('due' in body) {
    const due = validDate(body.due);
    if (due === undefined) return err('due must be an ISO date (YYYY-MM-DD) or null.', 400);
    if (due !== next.due) { next.due = due; changed.push('due'); }
  }
  if ('evidence' in body) {
    const evidence = cleanStr(body.evidence, 2000);
    if (evidence !== next.evidence) { next.evidence = evidence; changed.push('evidence'); }
  }

  const actor = getActor(request, body);
  next.updated_by = actor;
  next.updated_at = nowISO();

  await env.DB.prepare(
    `UPDATE tasks SET title = ?, details = ?, owner = ?, status = ?, due = ?, evidence = ?, updated_by = ?, updated_at = ?
     WHERE id = ?`
  )
    .bind(next.title, next.details, next.owner, next.status, next.due, next.evidence, next.updated_by, next.updated_at, id)
    .run();

  const statusChanged = next.status !== existing.status;
  await writeActivity(env, {
    taskId: id,
    actor,
    action: statusChanged ? 'status_changed' : 'updated',
    note: changed.length ? `${next.title} — ${changed.join('; ')}` : next.title,
  });

  const task = await env.DB.prepare('SELECT * FROM tasks WHERE id = ?').bind(id).first();
  return json({ task });
}

// ---- ./functions/api/digests.js ----
// POST /api/digests — publish a digest.
// Body: { title (required), body (required, markdown), date (optional, defaults to today), actor }

async function hDigestsPost({ request, env }) {
  const body = await parseBody(request);
  if (!body) return err('Body must be valid JSON.', 400);

  const title = cleanStr(body.title, 300).trim();
  if (!title) return err('title is required.', 400);

  const text = cleanStr(body.body, 60000);
  if (!text.trim()) return err('body is required.', 400);

  let date = todayISO();
  if (body.date !== undefined && body.date !== null && body.date !== '') {
    date = validDate(body.date);
    if (date === undefined || date === null) return err('date must be an ISO date (YYYY-MM-DD).', 400);
  }

  const actor = getActor(request, body);
  const result = await env.DB.prepare(
    'INSERT INTO digests (date, title, body, created_by, created_at) VALUES (?, ?, ?, ?, ?)'
  )
    .bind(date, title, text, actor, nowISO())
    .run();

  await writeActivity(env, { actor, action: 'digest_posted', note: title });

  const digest = await env.DB.prepare('SELECT * FROM digests WHERE id = ?')
    .bind(result.meta.last_row_id)
    .first();
  return json({ digest }, 201);
}

// ---- ./functions/api/digests/[id].js ----
// GET /api/digests/:id — one digest in full (the /api/state digest index
// only carries id/date/title, so the archive view fetches bodies through here).

async function hDigestGet({ env, params }) {
  const id = Number(params.id);
  if (!Number.isInteger(id) || id <= 0) return err('Invalid digest id.', 400);
  const digest = await env.DB.prepare('SELECT * FROM digests WHERE id = ?').bind(id).first();
  if (!digest) return err('Digest not found.', 404);
  return json({ digest });
}

// ---- ./functions/api/deadlines.js ----
// POST /api/deadlines — add a deadline.
// Body: { title (required), date (required), notes, owner, actor }

async function hDeadlinesPost({ request, env }) {
  const body = await parseBody(request);
  if (!body) return err('Body must be valid JSON.', 400);

  const title = cleanStr(body.title, 300).trim();
  if (!title) return err('title is required.', 400);

  const date = validDate(body.date);
  if (date === undefined || date === null) return err('date must be an ISO date (YYYY-MM-DD).', 400);

  const owner = validOwner(body.owner, 'Jesutofunmi');
  if (owner === undefined) return err('owner is not a recognised name.', 400);

  const actor = getActor(request, body);
  const result = await env.DB.prepare(
    'INSERT INTO deadlines (title, date, notes, owner, created_at) VALUES (?, ?, ?, ?, ?)'
  )
    .bind(title, date, cleanStr(body.notes, 2000), owner, nowISO())
    .run();

  await writeActivity(env, { actor, action: 'deadline_added', note: `${title} (${date})` });

  const deadline = await env.DB.prepare('SELECT * FROM deadlines WHERE id = ?')
    .bind(result.meta.last_row_id)
    .first();
  return json({ deadline }, 201);
}

// ---- ./functions/api/deadlines/[id].js ----
// PATCH /api/deadlines/:id — partial update of title, date, notes, owner.

async function hDeadlinePatch({ request, env, params }) {
  const id = Number(params.id);
  if (!Number.isInteger(id) || id <= 0) return err('Invalid deadline id.', 400);

  const existing = await env.DB.prepare('SELECT * FROM deadlines WHERE id = ?').bind(id).first();
  if (!existing) return err('Deadline not found.', 404);

  const body = await parseBody(request);
  if (!body) return err('Body must be valid JSON.', 400);

  const next = { ...existing };

  if ('title' in body) {
    const title = cleanStr(body.title, 300).trim();
    if (!title) return err('title cannot be empty.', 400);
    next.title = title;
  }
  if ('date' in body) {
    const date = validDate(body.date);
    if (date === undefined || date === null) return err('date must be an ISO date (YYYY-MM-DD).', 400);
    next.date = date;
  }
  if ('notes' in body) next.notes = cleanStr(body.notes, 2000);
  if ('owner' in body) {
    const owner = validOwner(body.owner, 'Jesutofunmi');
    if (owner === undefined) return err('owner is not a recognised name.', 400);
    next.owner = owner;
  }

  await env.DB.prepare('UPDATE deadlines SET title = ?, date = ?, notes = ?, owner = ? WHERE id = ?')
    .bind(next.title, next.date, next.notes, next.owner, id)
    .run();

  const actor = getActor(request, body);
  await writeActivity(env, { actor, action: 'deadline_updated', note: `${next.title} (${next.date})` });

  const deadline = await env.DB.prepare('SELECT * FROM deadlines WHERE id = ?').bind(id).first();
  return json({ deadline });
}

// ---- ./functions/api/reports.js ----
// POST /api/reports — save a daily report.
// Body: { author (required, one of the five names), body (required, markdown),
//         date (optional, defaults to today), actor }
// One report per (date, author): posting again for the same pair replaces the
// body (upsert). The author is whose report it is; the actor is who posted it
// and lands in created_by — they differ when Instinct posts Jesutofunmi's
// report on her behalf.

async function hReportsPost({ request, env }) {
  await ensureReportsTable(env);

  const body = await parseBody(request);
  if (!body) return err('Body must be valid JSON.', 400);

  const author = validAuthor(body.author);
  if (author === undefined) {
    return err(`author is required and must be one of: ${ACTORS.join(', ')}.`, 400);
  }

  const text = cleanStr(body.body, 60000);
  if (!text.trim()) return err('body is required.', 400);

  let date = todayISO();
  if (body.date !== undefined && body.date !== null && body.date !== '') {
    date = validDate(body.date);
    if (date === undefined || date === null) return err('date must be an ISO date (YYYY-MM-DD).', 400);
  }

  const actor = getActor(request, body);
  const ts = nowISO();

  const existing = await env.DB.prepare('SELECT id FROM reports WHERE date = ? AND author = ?')
    .bind(date, author)
    .first();

  await env.DB.prepare(
    `INSERT INTO reports (date, author, body, created_by, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?)
     ON CONFLICT(date, author) DO UPDATE SET
       body = excluded.body,
       created_by = excluded.created_by,
       updated_at = excluded.updated_at`
  )
    .bind(date, author, text, actor, ts, ts)
    .run();

  await writeActivity(env, { actor, action: 'report_posted', note: `Daily report — ${author} (${date})` });

  const report = await env.DB.prepare('SELECT * FROM reports WHERE date = ? AND author = ?')
    .bind(date, author)
    .first();
  return json({ report }, existing ? 200 : 201);
}

